#include "forest_ui.h"
#include "card_art.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static u16 *frame[2];
static u16 *forestTop,*forestBottom,*table,*showcase,*emblem;static u8 font[95*8*13];
static int width(gfxScreen_t s){return s==GFX_TOP?400:320;}
static void pixel(gfxScreen_t s,int x,int y,u16 c){if(x<0||y<0||x>=width(s)||y>=240)return;frame[s==GFX_TOP?0:1][x*240+239-y]=c;}
static void *asset(const char *name,size_t bytes){char p[180];snprintf(p,sizeof(p),"sdmc:/3ds/ilex-gg/media/%s",name);FILE *f=fopen(p,"rb");if(!f)return NULL;void *v=malloc(bytes);if(v&&fread(v,1,bytes,f)!=bytes){free(v);v=NULL;}fclose(f);return v;}
static void transpose(u16 *p,int w){if(!p)return;u16 *temp=malloc(w*240*2);if(!temp)return;for(int x=0;x<w;x++)for(int y=0;y<240;y++)temp[x*240+239-y]=p[y*w+x];memcpy(p,temp,w*240*2);free(temp);}
void ilex_ui_init(void){frame[0]=(u16*)gfxGetFramebuffer(GFX_TOP,GFX_LEFT,NULL,NULL);frame[1]=(u16*)gfxGetFramebuffer(GFX_BOTTOM,GFX_LEFT,NULL,NULL);forestTop=asset("forest-top.565",400*240*2);forestBottom=asset("forest-bottom.565",320*240*2);table=asset("table.565",400*240*2);showcase=asset("showcase.565",162*226*2);emblem=asset("emblem.565",48*48*2);u8 *f=asset("font.alpha",sizeof(font));if(f){memcpy(font,f,sizeof(font));free(f);}transpose(forestTop,400);transpose(forestBottom,320);transpose(table,400);}
void ilex_ui_exit(void){free(forestTop);free(forestBottom);free(table);free(showcase);free(emblem);}
void ilex_ui_image(gfxScreen_t s,const u16 *p,int sw,int sh,int x,int y,int w,int h){if(!p)return;for(int j=0;j<h;j++)for(int i=0;i<w;i++)pixel(s,x+i,y+j,p[(j*sh/h)*sw+i*sw/w]);}
void ilex_ui_box(gfxScreen_t s,int x,int y,int w,int h,u16 fill,u16 border){for(int j=0;j<h;j++)for(int i=0;i<w;i++){if((i<3||i>=w-3)&&(j<2||j>=h-2))continue;pixel(s,x+i,y+j,(i==0||j==0||i==w-1||j==h-1)?border:fill);}}
void ilex_ui_plaque(gfxScreen_t s,int x,int y,int w,int h,int selected){for(int j=0;j<h;j++){int cap=j<6?6-j:j>=h-6?j-(h-7):0;for(int i=cap;i<w-cap;i++){int rim=i==cap||i==w-cap-1||j==0||j==h-1;unsigned grain=((i/19+j*3)%5);u16 wood=selected?(0x2b05+grain*32):(0x19a3+grain*32);pixel(s,x+i,y+j,rim?ILEX_GOLD:wood);}}ilex_ui_box(s,x+6,y+h/2-1,3,3,ILEX_GOLD,ILEX_GOLD);ilex_ui_box(s,x+w-9,y+h/2-1,3,3,ILEX_GOLD,ILEX_GOLD);}
static void heading(gfxScreen_t s,int x,int y,const char *str){for(const unsigned char *p=(const unsigned char*)str;*p;p++){unsigned ch=*p>=32&&*p<=126?*p-32:'?'-32;for(int j=0;j<13;j++)for(int i=0;i<8;i++)if(font[ch*104+j*8+i]>100)for(int dy=0;dy<2;dy++)for(int dx=0;dx<2;dx++)pixel(s,x+i*2+dx,y+j*2+dy,ILEX_CREAM);x+=12;}}
void ilex_ui_background(gfxScreen_t s,const char *name){u16 *p=s==GFX_TOP?(!strcmp(name,"table")?table:forestTop):forestBottom;if(p)memcpy(frame[s==GFX_TOP?0:1],p,width(s)*240*2);else ilex_ui_box(s,0,0,width(s),240,0x11c5,0x11c5);}
void ilex_ui_text(gfxScreen_t s,int x,int y,const char *str,u16 c,int limit){int first=x,chars=0;for(const unsigned char *p=(const unsigned char*)str;*p&&y<232;p++){if(*p=='\n'){x=first;y+=14;chars=0;continue;}if(chars++>=limit)continue;unsigned ch=*p>=32&&*p<=126?*p-32:'?'-32;for(int j=0;j<13;j++)for(int i=0;i<8;i++)if(font[ch*104+j*8+i]>100)pixel(s,x+i,y+j,c);x+=6;}}
void ilex_ui_home(const char *title,const char *detail){ilex_ui_background(GFX_TOP,"forest");ilex_ui_image(GFX_TOP,showcase,162,226,244,17,143,200);ilex_ui_box(GFX_TOP,12,53,217,132,0x11a4,ILEX_GOLD);ilex_ui_image(GFX_TOP,emblem,48,48,25,66,48,48);heading(GFX_TOP,86,77,"ILEX.GG");ilex_ui_text(GFX_TOP,26,124,title,ILEX_GOLD,32);ilex_ui_text(GFX_TOP,26,147,detail,ILEX_CREAM,32);}
void ilex_ui_panel(const char *title,const char *body,const char *footer){ilex_ui_background(GFX_BOTTOM,"forest");ilex_ui_box(GFX_BOTTOM,6,5,308,26,0x1a05,ILEX_GOLD);ilex_ui_text(GFX_BOTTOM,15,12,title,ILEX_CREAM,48);ilex_ui_box(GFX_BOTTOM,6,36,308,166,0x11c4,0x5bcb);ilex_ui_text(GFX_BOTTOM,14,43,body,ILEX_CREAM,48);ilex_ui_text(GFX_BOTTOM,10,215,footer,ILEX_GOLD,50);}
void ilex_ui_choices(JSContext *ctx,JSValueConst v,unsigned cursor,int count,unsigned handCursor,int handFocus,const char *error,const char *status){
 ilex_ui_background(GFX_BOTTOM,"forest");JSValue t=JS_GetPropertyStr(ctx,v,"title"),rs=JS_GetPropertyStr(ctx,v,"rows");const char *ts=JS_ToCString(ctx,t);ilex_ui_box(GFX_BOTTOM,5,4,310,35,0x1a05,ILEX_GOLD);ilex_ui_text(GFX_BOTTOM,12,9,ts?ts:"Your turn",ILEX_CREAM,48);JS_FreeCString(ctx,ts);JS_FreeValue(ctx,t);
 unsigned first=cursor/ILEX_CHOICE_PAGE*ILEX_CHOICE_PAGE;for(unsigned i=first;i<first+ILEX_CHOICE_PAGE&&i<(unsigned)count;i++){int y=ILEX_CHOICE_Y+(i-first)*ILEX_CHOICE_HEIGHT;int selected=i==cursor&&!handFocus;ilex_ui_plaque(GFX_BOTTOM,7,y,244,15,selected);JSValue r=JS_GetPropertyUint32(ctx,rs,i);const char *s=JS_ToCString(ctx,r);ilex_ui_text(GFX_BOTTOM,13,y+1,s?s:"",selected?0xffb9:ILEX_CREAM,38);JS_FreeCString(ctx,s);JS_FreeValue(ctx,r);}JS_FreeValue(ctx,rs);
 JSValue hand=JS_GetPropertyStr(ctx,v,"hand"),cards=JS_IsObject(hand)?JS_GetPropertyStr(ctx,hand,"cards"):JS_UNDEFINED,length=JS_IsObject(cards)?JS_GetPropertyStr(ctx,cards,"length"):JS_UNDEFINED;int32_t n=0;JS_ToInt32(ctx,&n,length);JS_FreeValue(ctx,length);
 if(n>0){if(handCursor>=(unsigned)n)handCursor=n-1;unsigned start=handCursor/ILEX_HAND_PAGE*ILEX_HAND_PAGE;JSValue hint=JS_GetPropertyStr(ctx,hand,"hint");const char *hs=JS_ToCString(ctx,hint);char label[100];snprintf(label,sizeof(label),"%s  %u-%u/%ld",hs?hs:"Your hand",start+1,start+7<(unsigned)n?start+7:(unsigned)n,(long)n);ilex_ui_text(GFX_BOTTOM,10,139,*error?error:label,*error?0xfb4c:ILEX_GOLD,50);JS_FreeCString(ctx,hs);JS_FreeValue(ctx,hint);
 for(unsigned i=start;i<start+7&&i<(unsigned)n;i++){JSValue c=JS_GetPropertyUint32(ctx,cards,i),id=JS_GetPropertyStr(ctx,c,"id"),enabled=JS_GetPropertyStr(ctx,c,"enabled"),selected=JS_GetPropertyStr(ctx,c,"selected");int32_t ordinal=0;JS_ToInt32(ctx,&ordinal,selected);int x=16+(i-start)*41,highlight=i==handCursor&&handFocus;ilex_ui_box(GFX_BOTTOM,x-2,ILEX_HAND_Y-2,41,56,0x11c4,highlight||ordinal?ILEX_GOLD:JS_ToBool(ctx,enabled)?ILEX_GREEN:0x528a);const char *cs=JS_ToCString(ctx,id);if(cs&&*cs)ilex_card_draw_bottom(cs,x,ILEX_HAND_Y,37,52);if(ordinal){char mark[8];snprintf(mark,sizeof(mark),"%ld",(long)ordinal);ilex_ui_box(GFX_BOTTOM,x,ILEX_HAND_Y,10,12,0x11c4,ILEX_GOLD);ilex_ui_text(GFX_BOTTOM,x+2,ILEX_HAND_Y,mark,ILEX_GOLD,2);}JS_FreeCString(ctx,cs);JS_FreeValue(ctx,id);JS_FreeValue(ctx,enabled);JS_FreeValue(ctx,selected);JS_FreeValue(ctx,c);}
 ilex_ui_text(GFX_BOTTOM,2,176,"<",ILEX_GOLD,1);ilex_ui_text(GFX_BOTTOM,309,176,">",ILEX_GOLD,1);
 }else if(*error)ilex_ui_text(GFX_BOTTOM,10,139,error,0xfb4c,50);
 JS_FreeValue(ctx,cards);JS_FreeValue(ctx,hand);

 char page[40];snprintf(page,sizeof(page),"%u / %u",count?cursor+1:0,count);if(count)ilex_ui_text(GFX_BOTTOM,263,121,page,ILEX_GOLD,9);
 ilex_ui_text(GFX_BOTTOM,10,215,"A Choose  X Inspect  Y Save  L/R Actions",ILEX_CREAM,50);ilex_ui_text(GFX_BOTTOM,10,229,"Left/Right Hand  START Pause  SELECT Audio",ILEX_GOLD,50);
}
void ilex_ui_progress(const char *title,int n,int total){char buf[80];snprintf(buf,sizeof(buf),"%d / %d saved actions\n\nB Cancel",n,total);ilex_ui_home("Restoring your match","Replaying saved actions");ilex_ui_panel(title,buf,"Your SD save is preserved");ilex_ui_box(GFX_BOTTOM,18,142,284,14,0x11c4,ILEX_GOLD);int fill=total>0?280*n/total:0;if(fill>280)fill=280;ilex_ui_box(GFX_BOTTOM,20,144,fill,10,ILEX_GREEN,ILEX_GREEN);}
void ilex_ui_sparks(unsigned frame){for(int i=0;i<8;i++){int x=160+((i*31+frame*3)%88),y=76+((i*19+frame*2)%100);ilex_ui_box(GFX_TOP,x,y,2,2,ILEX_GOLD,ILEX_CREAM);}}
